arguments.new_str:
using System;
using System.Diagnostics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using TextAnalysis;

const int WarmupIterations = 100;
const int BenchmarkIterations = 10_000;

const string SampleText =
    "The quick brown fox jumps over the lazy dog. " +
    "A journey of a thousand miles begins with a single step. " +
    "To be or not to be that is the question. " +
    "All that glitters is not gold and not all those who wander are lost. " +
    "In the middle of difficulty lies opportunity and great responsibility.";

var analyzer = new TextAnalyzer(SampleText);

Console.WriteLine($"Runtime: {RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"Iterations: {BenchmarkIterations}");
Console.WriteLine();

// Warmup
for (int i = 0; i < WarmupIterations; i++)
{
    Consume(analyzer.AverageWordLength());
    Consume(analyzer.WordLengthHistogram());
    Consume(analyzer.UniqueWordCount());
}

// Benchmark AverageWordLength
var sw = Stopwatch.StartNew();
for (int i = 0; i < BenchmarkIterations; i++)
    Consume(analyzer.AverageWordLength());
sw.Stop();
Console.WriteLine($"AverageWordLength:   {sw.Elapsed.TotalMilliseconds:F3} ms total, {sw.Elapsed.TotalNanoseconds / BenchmarkIterations:F1} ns/op");

// Benchmark WordLengthHistogram
sw.Restart();
for (int i = 0; i < BenchmarkIterations; i++)
    Consume(analyzer.WordLengthHistogram());
sw.Stop();
Console.WriteLine($"WordLengthHistogram: {sw.Elapsed.TotalMilliseconds:F3} ms total, {sw.Elapsed.TotalNanoseconds / BenchmarkIterations:F1} ns/op");

// Benchmark UniqueWordCount
sw.Restart();
for (int i = 0; i < BenchmarkIterations; i++)
    Consume(analyzer.UniqueWordCount());
sw.Stop();
Console.WriteLine($"UniqueWordCount:     {sw.Elapsed.TotalMilliseconds:F3} ms total, {sw.Elapsed.TotalNanoseconds / BenchmarkIterations:F1} ns/op");

[MethodImpl(MethodImplOptions.NoInlining)]
static void Consume<T>(T value) { }

