arguments.new_str:
using System;
using System.Diagnostics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using TextAnalysis;

const int WarmupIterations = 5000;
const int BenchmarkIterations = 200_000;
const int Runs = 5;

const string SampleText =
    "The quick brown fox jumps over the lazy dog. " +
    "A journey of a thousand miles begins with a single step. " +
    "To be or not to be that is the question. " +
    "All that glitters is not gold and not all those who wander are lost. " +
    "In the middle of difficulty lies opportunity and great responsibility.";

var analyzer = new TextAnalyzer(SampleText);

Console.WriteLine($"Runtime: {RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"Iterations per run: {BenchmarkIterations}, Runs: {Runs} (taking median)");
Console.WriteLine();

// Warmup
for (int i = 0; i < WarmupIterations; i++)
{
    Consume(analyzer.AverageWordLength());
    Consume(analyzer.WordLengthHistogram());
    Consume(analyzer.UniqueWordCount());
}

double[] avgResults = new double[Runs];
double[] histResults = new double[Runs];
double[] uniqResults = new double[Runs];

for (int r = 0; r < Runs; r++)
{
    var sw = Stopwatch.StartNew();
    for (int i = 0; i < BenchmarkIterations; i++)
        Consume(analyzer.AverageWordLength());
    sw.Stop();
    avgResults[r] = sw.Elapsed.TotalNanoseconds / BenchmarkIterations;

    sw.Restart();
    for (int i = 0; i < BenchmarkIterations; i++)
        Consume(analyzer.WordLengthHistogram());
    sw.Stop();
    histResults[r] = sw.Elapsed.TotalNanoseconds / BenchmarkIterations;

    sw.Restart();
    for (int i = 0; i < BenchmarkIterations; i++)
        Consume(analyzer.UniqueWordCount());
    sw.Stop();
    uniqResults[r] = sw.Elapsed.TotalNanoseconds / BenchmarkIterations;
}

Array.Sort(avgResults);
Array.Sort(histResults);
Array.Sort(uniqResults);

int mid = Runs / 2;
Console.WriteLine($"AverageWordLength:   {avgResults[mid]:F1} ns/op (median)");
Console.WriteLine($"WordLengthHistogram: {histResults[mid]:F1} ns/op (median)");
Console.WriteLine($"UniqueWordCount:     {uniqResults[mid]:F1} ns/op (median)");

[MethodImpl(MethodImplOptions.NoInlining)]
static void Consume<T>(T value) { }

